#!/usr/bin/env python3
import sys, time, random

def send(msg):
    sys.stdout.write(msg + "\n")
    sys.stdout.flush()

# initial id lines (some GUIs expect after 'uci', but send now ok)
send("id name FakeEngine")
send("id author Gym_Puzzle")

while True:
    line = sys.stdin.readline()
    if not line:
        break
    cmd = line.strip()
    if cmd == "uci":
        send("id name FakeEngine")
        send("id author Gym_Puzzle")
        send("uciok")
    elif cmd == "isready":
        send("readyok")
    elif cmd.startswith("setoption"):
        # ignore any option settings
        pass
    elif cmd.startswith("ucinewgame"):
        pass
    elif cmd.startswith("position"):
        # we could parse FEN but unnecessary
        pass
    elif cmd.startswith("go"):
        # Provide a very negative score from White's perspective
        send("info score cp -1000")
        # Provide some dummy bestmove (0000 is allowable for none)
        send("bestmove 0000")
    elif cmd == "quit":
        break
    else:
        # respond ok to stop and other commands if needed
        if cmd == "stop":
            send("bestmove 0000")
        # else ignore unknowns
        pass
